package com.treepeople.leapmindtts.service.profile.platform;
import java.math.BigDecimal; import java.time.Instant; import java.util.List;
public record PracticeProfileContext(Long userId, String sceneType, ProfileContextStatus profileStatus, String statusReason, Long profileVersion, Instant computedAt, Instant lastUpdated, BigDecimal confidence, ProfileAvailability availability, List<ProfileKnowledgeContext> knowledgeStatuses, List<ProfileKnowledgeContext> weakKnowledgePoints, String learningPace, List<String> preferredContentModes) {
    public PracticeProfileContext { boolean facts = !(ProfileContextFields.list(knowledgeStatuses).isEmpty() && ProfileContextFields.list(weakKnowledgePoints).isEmpty() && learningPace == null && ProfileContextFields.list(preferredContentModes).isEmpty()); ProfileContextFields.envelope(userId, sceneType, "practice", profileStatus, statusReason, profileVersion, computedAt, lastUpdated, confidence, availability, facts); knowledgeStatuses = ProfileContextFields.list(knowledgeStatuses, 100, "knowledgeStatuses"); weakKnowledgePoints = ProfileContextFields.list(weakKnowledgePoints, 100, "weakKnowledgePoints"); learningPace = ProfileContextFields.pace(learningPace); preferredContentModes = ProfileContextFields.contentModes(preferredContentModes); }
}
